import math
from typing import List

MOD = 10**9 + 7

def is_haiku(s: List[int], x, y, z):
    sum_x = sum(s[i] for i in range(x-1, y))
    sum_y = sum(s[i] for i in range(y-1, z))
    sum_z = sum(s[i] for i in range(z-1, len(s)))
    return sum_x == x and sum_y == y and sum_z == z

def count_sequences(N: int, X: int, Y: int, Z: int):
    dp = [0] * (X+Z+1)
    dp[0] = 1
    for N_iter in range(1, N+1):
        new_dp = [0] * (X+Z+1)
        for current_sum in range(X+Z+1):
            for x_sum in range(1, math.isqrt(current_sum) + 1):
                if x_sum * 5 > current_sum and current_sum - x_sum * 5 > 0:
                    if is_haiku(s[:] + [x_sum*5], N_iter-1, x_sum-1, x_sum*5 - x_sum):
                        new_dp[current_sum+x_sum*5] += dp[current_sum]
                        new_dp[current_sum+x_sum*5] %= MOD
        dp, new_dp = new_dp, dp

    return dp[X+Y+Z]

if __name__ == "__main__":
    N, X, Y, Z = map(int, input().split())
    print(count_sequences(N, X, Y, Z))
