    def dfs(start, used):
        if (start, tuple(used)) in memo:
            return memo[(start, tuple(used))]
        if start == len(w):
            return 1
        min_reps = 0
        for expected in range(start, len(w)):
            if w[start:expected+1] not in memo:
                good = True
