                    memo[(start, tuple(sorted(w[start:expected+1])))] += dfs(expected, used + (tuple(sorted(w[start:expected+1])),))
                    if memo[(start, tuple(sorted(w[start:expected+1])))] >= mod * 2:
                        return mod * 2
            min_reps = max(min_reps, dfs(expected + 1, used))
