from math import pow

def min_operations(index, end, w, memo=None):
    if memo is None:
        memo = [-1] * len(w)
    if index - 1 >= 0:
        memo[index] = (memo[index - 1] + w[index - 1]) % 1000000007
    if index == len(w) - 1:
        return 0 if w[index] == w[0] else 1
    if memo[index] != -1:
        return memo[index]

    i = index
    res = 1
    mod = pow(1000000007, 1, 1000000007)
    while i + 1 < end:
        help = pow(2, res, 1000000007)
        res += 1
        if help != 0:
            res = pow(help, 1, 1000000007)
        else:
            return mod * pow(2, mod, 1000000007) % 1000000007
        i += 1
    end = min(w[index], res + 1)

    if res + min_operations(i + 1, end, w) < min_operations(index + 1, end, w):
        memo[index] = res + 1
    else:
        memo[index] = 2

    return memo[index % len(w)]

def main():
