from collections import defaultdict

def update_digit(x, old, new):
    result = x
    result = str(result)
    for i, digit in enumerate(result):
        if digit == old:
            result[i] = new
        result = str(result[i:])
    return int(result)

class ChangeDatabase:
    def __init__(self, n):
        self.n = n
        self.subarrays = defaultdict(self._default_subarray)

        # Create default subarray for initially given array
        for i in range(n):
            self.subarrays[i] = self.get_subarray_from_list([0] * n)

    @staticmethod
    def _default_subarray():
        return [-1] * (10 ** 9 - 1 + 1)

    def _get_current_subarray(self, l, r):
        result = self.subarrays[r]
        if l - 1 > 0:
            result = result[:l - 1]
        return [result[i] - self.subarrays[l - 1][i] for i in range(10)]

    def change_digit(self, l, r, x, y):
        orig_list = [0] * self.n
        orig_list[l - 1] = x
        orig_list[r] = y

        orig_subarray = self.get_subarray_from_list(orig_list)
        current_subarray = self.subarrays[r]
        actual_subarray = self._get_current_subarray(l - 1, r)
        diff_list = [(actual_subarray[i] - current_subarray[i]) for i in range(10)]

        new_list = [num if num == orig_list[i] else update_digit(num, orig_list[l - 1], orig_list[r]) for i, num in enumerate(orig_list)]
        change_list = [0 if i < l - 1 else -i for i in range(-l + l + 1, 10)]

        for digit in range(10):
            current_subarray[digit] += diff_list[digit] - change_list[digit]

        self.subarrays[r] = (new_list, current_subarray)

    def get_subarray_from_list(self, list_arr):
        prefix_sum = [0] * (len(list_arr) + 1)
        for idx, value in enumerate(list_arr):
            prefix_sum[idx + 1] = prefix_sum[idx] + value
        return prefix_sum


