from collections import deque

def shortest_path(maps, k):
    n, m, k = len(maps[0]), len(maps), len(list(maps[0].keys()))
    visited = [[[0]*k for _ in range(m)] for _ in range(n)]
    queue = deque([(k, 0, 0, 0, '')])
    while queue:
        dist, d, y, x, path = queue.popleft()
        for ny, nx in [(y+1, x), (y-1, x), (y, x+1), (y, x-1)]:
            if 0 <= ny < n and 0 <= nx < m:
                if (maps[ny][nx] == 'T' or maps[ny][nx] == path[-1]) and visited[ny][nx][d] <= dist + 1:
                    visited[ny][nx][d] = dist + 1
                    if maps[ny][nx] == 'S':
                        if d == 0:
                            return path + maps[ny][nx], visited[ny][nx][d]
                    else:
                        queue.append((visited[ny][nx][d], d, ny, nx, path + maps[ny][nx]))
    return -1

