# Function to compute fr(n) using memoization
def memoized_fr(n):
    if n in memo:
        return memo[n]

    result = 0
    for i in range(1, n):
        if gcd(i, n - i) == 1:
            result = (result + fr(n - i)) % MOD
    memo[n] = result
    return result

# Function to include gcd calculation in a way that fits the problem constraints
def gcd(x, y):
    while(y):
        x, y = y, x % y
