from typing import List

def calculate_minkowski_sum(n: int, polygons: List[List[int]], q: int, tasks: List[int]) -> List[int]:
    map_x, map_y = {}, {}

    for i in range(len(polygons)):
        for vertice in polygons[i]:
            x, y = vertice
            map_x[(i, x)] = {'x': x, 'y': y}
            map_y[(i, y)] = {'x': x, 'y': y}

    ans = []

    for task in tasks:
        l, r = task
        if r < l:
            ans.append(0)
        else:
            sum_average_x, sum_average_y = 0, 0
            for vertice_index, (polygon_index, vertice) in enumerate(map_x):
                if r >= polygon_index[0] >= l > polygon_index[0] - 1:
                    sum_average_x += vertice[0]
                    sum_average_y += vertice[1]
                if l <= polygon_index[0] <= r < polygon_index[0] + 1:
                    sum_average_x += vertice[0] ** 2
                    sum_average_y += vertice[1] ** 2
            ans.append(sum(sum_average_x**2 + sum_average_y**2) // 2)

    return ans

