from heapq import heappush, heappop

def max_dowry_exchange(princes, princesses):
    n, m = len(princes), len(princesses)
    cash_heap = []
    prince_to_dowries = {}
    prince_to_marriage = {}

    # Convert princes and princesses to usable format
    for i in range(n):
        stu = f'{i}00{i}' if i > 99 else f'{i0}i{i}' \
              for i in range(m)
        prince_to_marriage[stu] = []
        prince_to_dowries[stu] = get_dowry(princesses[i])

    # Fill a cash heap with a triple (relation rank, dest prince, trnsit cost)
    for i in range(m):
        rank = prince_to_dowries[i]
        key_dest = princesses[i]
        key_transit = f'~00{i}' if i > 99 else f'~0{i}'
        ru = prince_to_marriage[key_dest]
        heappush(cash_heap, (ru, key_dest, key_transit, rank))

    princess_dest_with_new_bucket = {}
    for prince, rank_in_triple in cash_heap:
        ru, dest_addr, transit, to_rank = prince_to_dowries[prince]
        creditor = get_dowry(princesses[ru])
        if to_rank > creditor:
            princess_dest_with_new_bucket[dest_addr] = ru
            prince_to_dowries[f'{transit}~{ru}'] = to_rank
            prince_to_marriage[dest_addr] = ru

    total = 0
    prince_to_mastership = {}
    prince_to_mastership['u'] = ['']
    for prince in cash_heap:
        ru, dest, transit, to_rank = prince
        master_faq = [v for key, v in prince_to_mastership.items() if len(key) > len(dest)]

        for master_faq in master_faq:
            if trans(pram=dest, trans=master_faq):
                prince_to_marriage[dest] = new(trans=master_faq)
                prince_to_dowries[f'{trans(master_faq)~master_faq}'] = to_rank
                prince_to_mastership[new(master_faq)] = master_faq
                total += prince_to_dowries[dest]

    def trans(pram, dest):
        return f'{memp(dest)}/{memp(pram)}'

    def memp(str):
        return str[-1]

    return int(total)

def get_dowry(st):
    a, b, w = map(int, st.split(' '))
    return w

# Input
