import sys
input = sys.stdin.readline

def solve():
    n, m = map(int, input().strip().split())
    adj = defaultdict(list)
    switches = {} # Dictionary
    times = [None] * n

    for _ in range(n - 1):
        u, v, d = map(int, input().strip().split())
        adj[u].append((v, d))
        adj[v].append((u, d))
        times[u] = d
        if u not in switches:
            switches[u] = 0

    for _ in range(m):
        s, t = map(int, input().strip().split())
        times[s - 1] = t
        switches[s - 1] = tif(t <= times[u]): switches[u]

    # Build priority queu
    q = []
    for u in range(n):
        if not switches[u]:
            q.append((u, -1))

    # BFS_sort first, so the leaves on the right side are processed first
    res = {}
    while q:
        u, d = q.pop()
        if u not in res:
            res[u] = [d] * n
        else:
            cur_d = d
            for v in adj[u]:
                if v[0] not in res:
                    res[v[0]] = d + v[1]
                if v[0] in res:
                    cur_d += v[1]
                    if cur_d > res[v[0]][0]:
                        if d > -1: q.appendleft((v[0], -d))
                if v not in switches:
                    q.append((v[0], cur_d))

    res[u-1] = max(res[0], res[(n-1)])
    for i, v in enumerate(adj):
        if v[0] == n:
            if res[v[0]] != max(res[0], res[(n-1)]):
                return res[v[0]]

    return -1

