import sys

def read_input():
    n, m = map(int, input().split())
    railroads = []
    for _ in range(n - 1):
        u, v, d = map(int, input().split())
        railroads.append((u, v, d))
    return n, m, railroads

def find_station_with_switch(i, railroads, switches):
    for j, (u, v, d) in enumerate(railroads):
        if u == i:
            if not switches:
                return v
            switches[i] = v
            break
    return i

def get_distance(start, visited, distances, station, railroads):
    if station in visited:
        return 0
    visited.add(station)
    min_distance = sys.maxsize
    direction = find_station_with_switch(station, railroads, visited)
    if direction == -1:
        return sys.maxsize
    for j, (u, v, d) in enumerate(railroads):
        if u != station and visited[u] and abs(visited[u] - direction) != 1:
            return sys.maxsize
    for j, (u, v, d) in enumerate(railroads):
        if u == direction and u != station:
            return -sys.maxsize
        dist = distances[u-1] 
        for k in range(min(direction, u), max(direction, v)+1):
            if visited[k]:
                dist += distances[k-1]
        if dist < distances[station]:
            distances[station] = dist
    return float('inf')

def get_minimum_switch_changes(n, railroads, distances, s_time, t_time):
    mini = sys.maxsize
    for v in range(2, n + 1):
        dis = get_distance(1, {1}, distances, v, railroads)
        time = dis / t_time
        if time < 0:
            continue
        if time > 0 and time > mini:
            mini = time
    return int(mini > 0 and mini < t_time)

def main():
    n, m = read_input()
    railroads = [tuple(map(int, input().split())) for _ in range(n - 1)]
    distances = [0] * n
    s_times, t_times = [], []
    switches = [None] * n
    for i in range(n):
        s, t = input().split()
        s_times.append(int(s))
        t_times.append(int(t))

    for t_time in t_times:
        for time, station in enumerate(s_times):
            mini = get_minimum_switch_changes(n, railroads, distances, station, t_time)
            if mini > 0 and mini < t_time:
                mini = time

    print(mini)
    print(t_time - mini)

if __name__ == "__main__":
