    in_degree = [0] * n
    for u, v in edges:
        in_degree[v-1] += 1

    min_heap = [(0, start)]
    dist = [float("inf")] * n
    dist[start] = 0

    while min_heap:
        dist_cost, node = heapq.heappop(min_heap)
        if dist[node] < dist_cost:
            continue
        for nbr in edges[node]:
            dist_nbr = dist_cost + (1 if nbr not in seen else 0)
            if dist_nbr < dist[nbr-1]:
                heapq.heappush(min_heap, (dist_nbr, nbr))
                dist[nbr-1] = dist_nbr
                in_degree[nbr-1] -= 1

    reachable = [v for v, d in enumerate(dist) if d < float("inf")]
    if 0 not in in_degree:
        to_return = [start]
        for k in reachable:
            to_return.append(nbr)
        return "".join(to_return)

    for u in reachable:
        times = {-1: "b", 0: "c", 1: "d", 2: "e"}
        min_so_far = float("inf")
        for v in reachable:
            our_time = dist[u-1] + (1 if in_degree[v-1] > 1 else 0)
            goal_time = dist[v-1] + (1 if in_degree[u-1] > 1 else 0)
            if our_time < min_so_far and goal_time < float("inf"):
                min_so_far = min_so_far if min_so_far < float("inf") else our_time
        if min_so_far < float("inf") and times[min_so_far] != seen[u-1]:
            seen[u-1] = times[min_so_far]
        return ""
    return ""

