import sys

def solve(N, M, P, days):
    dp = [0] * (2 * N + 1)

    for i in range(1, 2 * N + 1, 2):
        dp[i] = dp[i - 1]

    for j in range(2, 2 * N + 1, 2):
        if j - 2 >= dp[0]:
            dp[j - 2] += max(dp[j - 1])

    for j in range(2 * N + 1 - M // 2, 0, -2):
        if dp[j] + max(dp[j + 4 * N + 1 - M // 2]) * 2 - 1 <= sys.maxsize:
            dp[j] = max(dp[j], dp[j + 1] * 2 + max(dp[j] + max(dp[j + 4 * N + 1 - M // 2]), dp[j + 3]))

    return max(dp[0], dp[M // 2 + 1])

