def minOperations(S, T):
    if T == "":
        return 0 if S == "" else -1

    n, m = len(S), len(T)

    # String S doesn't contain Suffix of T
    for i in range(m)[::-1]:
        if T[i] != S[-(m - i - 1)]:
            return -1
    for i in range(m)[::-1]:
        S = S[:-1] + S[-1]

    # String S doesn't contain Prefix of T
    for i in range(m)[::-1]:
        if S[i] != T[-(m - i - 1)]:
            return -1
    for i in range(m):
        S = S[1:] + S[0]

    # If length of S differs from T
    if len(S) != m:
        return -1

    return minOperations(S, S[:n])

