from collections import deque

def bfs_path(g, start, end, forbidden_types):
    queue = deque([(start, 0, [start])])
    visited = set([start])
    path_queue = []
    path = []

    while queue:
        current, time, path = queue.popleft()
        if current == end:
            path_queue.append(path)
        for neighbor in g[current].keys() - forbidden_types:
            if neighbor not in visited:
                path.append(neighbor)
                visited.add(neighbor)
                queue.append((neighbor, time + 1, path[::]))
                if neighbor == end:
                    path_queue.append(path)
                break
        else:
            if current != start and neighbor == end:
                path.pop()
    return min([tuple(sorted(path)) for path in path_queue], key=sum)

