from collections import defaultdict

def get_prime_factors(n):
    i = 2
    factors = []
    while i * i <= n:
        if n % i:
            i += 1
        else:
            n //= i
            factors.append(i)
    if n > 1:
        factors.append(n)
    return factors

w = input()

# Count good strings of length n
good_strings_count = defaultdict(int)
for i in range(2, len(w) + 1):
    factors = get_prime_factors(i)
    for factor in factors:
        for j in range(2, len(w) + 1):
            if len(get_prime_factors(j)) == len(factors):
                good_strings_count[(i, j)] = 1
                for k in range(j - len(factors) + 1, j + 1):
                    good_strings_count[(i, k)] = 0

# Find the best representation and their counts
best_rep_count = defaultdict(int)
for k in good_strings_count:
    count = 1
    current = k
    while good_strings_count[(current[0], current[1])] == 1:
        current = (good_strings_count[(current[0], current[1])], current[1])
        count += 1
    best_rep_count[current] = count

# Print the number of elements and best representations modulo 1000000007
print(len(best_rep_count))
print(best_rep_count.values().__next__() % (10**9 + 7))
