def max_dowry(marriages):
    n, m = map(int, marriages.splitlines()[0].split())
    princesses = sorted([tuple(map(int, line.split())) for line in marriages.splitlines()[1:]], key=lambda x: x[2])
    dp = [0 for _ in range(m)]
    dp[0] = princesses[0][2]
    for i in range(1, m):
        max_dowry = 0
        for prince, girl in princesses[i:]:
            less_preferred_prince = False
            princesses_of_interest = princesses[0:i]
            # Check if the prince is not preferred for all preferred princesses
            for _, preferred_girl in princesses_of_interest:
                if prince != preferred_girl:
                    # Calculate the total dowry if the prince is not preferred for this princess
                    max_dowry += preferred_girl[2] * (m - i)
            if max_dowry < dp[i-1]:
                dp[i] = dp[i-1]
            else:
                dp[i] = max_dowry
    return max(dp)

# Example usage:
marriage_info = "2 3\n1 2 5\n1 2 1\n2 1 10"
print(max_dowry(marriage_info))
