import sys

def min_operations(S):
    if S == T:
        return 0
    if len(S) % 2 != len(T) % 2 or len(T) < len(S) or len(S) < len(T):
        return -1
    diff = 0
    for i in range(min(len(S), len(T))):
        diff += S[i] != T[i]
    half_diff = diff // 2

    if len(S) > len(T):
        half_diff_step1 = half_diff % 2
        if half_diff_step1 == 0:
            half_diff += 1
        half_diff_step2 = half_diff // 2
    else:
        half_diff_step1 = half_diff % 2
        half_diff_step2 = half_diff // 2

    return min(half_diff_step1 * 2 + half_diff_step2 + (half_diff // 2) * 2, half_diff_step1 * 2 + half_diff_step2)

T = int(input())
for _ in range(T):
    N, M = map(int, input().split())
    S = input()
    T = input()
    print(min_operations(S))
